const escape = (s = '') => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const ASSETS = new URL('./assets/', import.meta.url).href;
const image = (name, alt = '', cls = '') => `<img class="${cls}" src="${ASSETS}${name==='favicon'?name+'.svg':'v2/'+name+'.png'}" alt="${escape(alt)}">`;
const actionImage = (action, cls = '') => image(`action-${['reading','helping','searching','traffic','writing','taking','sweeping','walking','fallen'].includes(action) ? action : 'reading'}`, '', cls);
const lines = (n = 2, cls = '') => `<div class="writing ${cls}">${Array.from({ length: n }, () => '<div></div>').join('')}</div>`;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
