function page(title, inner, options = {}, number = 1, total = 1, layout = '') {
  return `<section class="page ${layout}"><header class="masthead"><div class="brand">OPS <em>ImAn</em></div><div class="material">${options.teacher ? '<span class="teacher-tag">SALINAN GURU · </span>' : ''}${escape(title)}<br><span class="small">${number} / ${total} · ${options.ink ? 'Jimat dakwat' : 'Berwarna'}</span></div></header><main class="content">${inner}</main><footer class="footer"><span>Bandar ImAn · Polis pembantu komuniti</span><span>${options.teacher ? 'Bukti pembelajaran menyokong pertimbangan guru.' : 'Berusaha · Berbahasa · Membantu'}</span></footer></section>`;
}
function identity(o) { return `<div class="identity"><span>Nama: <span class="field">${escape(o.name)}</span></span><span>Kelas: <span class="field">${escape(o.className)}</span></span></div>`; }
function curriculum(o) {
  const c={...CURRICULUM,...o.content?.curriculum};
  return `<b>Kurikulum:</b> ${escape(c.sk)}<br>${escape(c.sp)}<br><span class="small">${escape(c.document)} · ${c.confirmed?'Padanan disemak guru.':'Guru boleh menyunting dan menyemak padanan dengan DSKP yang digunakan.'}</span>`;
}
function pages(title, arr, options, layout = '') { return arr.map((s, i) => page(title, s, options, i + 1, arr.length, layout)).join(''); }
function resolvedItems(options) {
  const bank = options.content?.items || options.content;
  return ITEMS.map(item => ({...item, ...(Array.isArray(bank) ? bank.find(x => x.id === item.id) : bank?.[item.id])}));
}
function safeChoices(item) {
  return (item.choices || []).map(c => typeof c === 'object' ? (c.label || c.text || c.value || '') : c).filter(Boolean).slice(0, 4);
}
function challengeArt(item) {
  const actions=[item.action];
  return actions.length===1?actionImage(actions[0],'art'):`<div style="display:flex;height:35mm;gap:2mm">${actions.map(a=>actionImage(a,'art')).join('')}</div>`;
}

/** A seeded perfect maze. The six stops lie on its unique start-to-finish route. */
export function createPrintMaze() {
  const width = 31, height = 15;
  const grid = Array.from({ length: height }, () => Array(width).fill(1));
  let seed = 24106;
  const random = n => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed % n; };
  const stack = [[1, 1]]; grid[1][1] = 0;
  while (stack.length) {
    const [x,y] = stack.at(-1);
    const next = [[2,0],[-2,0],[0,2],[0,-2]].filter(([dx,dy]) => x+dx>0 && x+dx<width-1 && y+dy>0 && y+dy<height-1 && grid[y+dy][x+dx]);
    if (!next.length) { stack.pop(); continue; }
    const [dx,dy] = next[random(next.length)]; grid[y+dy/2][x+dx/2]=0; grid[y+dy][x+dx]=0; stack.push([x+dx,y+dy]);
  }
  const start = [1,1], end = [width-2,height-2], queue = [start], seen = new Map([['1,1',null]]);
  for (let i=0;i<queue.length;i++) {
    const [x,y]=queue[i]; if(x===end[0]&&y===end[1])break;
    for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {const nx=x+dx,ny=y+dy,key=`${nx},${ny}`;if(grid[ny]?.[nx]===0&&!seen.has(key)){seen.set(key,[x,y]);queue.push([nx,ny]);}}
  }
  const path=[]; let at=end; while(at){path.unshift(at);at=seen.get(at.join(','));}
  const stops=Array.from({length:6},(_,i)=>path[Math.round((path.length-1)*(i+1)/7)]);
  return {width,height,grid,start,end,path,stops};
}
function mazeSvg({ half = null, ink = false } = {}) {
 const m=createPrintMaze(),cell=32,pad=12,W=m.width*cell+pad*2,H=m.height*cell+pad*2;
 let shapes=`<rect width="${W}" height="${H}" fill="white"/><rect x="${pad}" y="${pad}" width="${m.width*cell}" height="${m.height*cell}" fill="${ink?'#e5e5e5':'#16a34a'}"/>`;
 m.grid.forEach((row,y)=>row.forEach((v,x)=>{const X=pad+x*cell,Y=pad+y*cell;if(v){if((x+y)%4===0)shapes+=`<rect x="${X+6}" y="${Y+7}" width="20" height="19" rx="3" fill="${ink?'#a9a9a9':'#102a56'}"/><path d="M${X+9} ${Y+12}h4m4 0h5m-13 7h4m4 0h5" stroke="${ink?'white':'#ffc400'}" stroke-width="2"/>`;return;}shapes+=`<rect x="${X}" y="${Y}" width="${cell+.1}" height="${cell+.1}" fill="${ink?'white':'#303642'}"/>`;for(const [dx,dy]of[[0,-1],[1,0],[0,1],[-1,0]]){if(m.grid[y+dy]?.[x+dx]===0)shapes+=`<path d="M${X+16+dx*6} ${Y+16+dy*6}l${dx*7} ${dy*7}" stroke="${ink?'#aaa':'white'}" stroke-width="1.2"/>`;else{const edge=dx===-1?`M${X+1} ${Y}v32`:dx===1?`M${X+31} ${Y}v32`:dy===-1?`M${X} ${Y+1}h32`:`M${X} ${Y+31}h32`;shapes+=`<path d="${edge}" stroke="${ink?'#888':'#e1e9f0'}" stroke-width="2"/>`;}}}));
 m.stops.forEach(([x,y],i)=>{const cx=pad+(x+.5)*cell,cy=pad+(y+.5)*cell;shapes+=`<rect x="${cx-15}" y="${cy-15}" width="30" height="30" rx="5" fill="white" stroke="${ink?'#222':'#ffc400'}" stroke-width="2"/><image href="${ASSETS}v2/location-${i+1}.png" x="${cx-15}" y="${cy-15}" width="30" height="28"/><circle cx="${cx+10}" cy="${cy+10}" r="8" fill="${ink?'white':'#ffc400'}" stroke="#102a56"/><text x="${cx+10}" y="${cy+14}" text-anchor="middle" font-family="Arial" font-size="11" font-weight="bold" fill="#102a56">${i+1}</text>`;});
 [[m.start,'M'],[m.end,'T']].forEach(([[x,y],label])=>{const cx=pad+(x+.5)*cell,cy=pad+(y+.5)*cell;shapes+=`<rect x="${cx-14}" y="${cy-14}" width="28" height="28" rx="4" fill="white" stroke="#102a56"/><text x="${cx}" y="${cy+6}" text-anchor="middle" font-family="Arial" font-size="18" font-weight="bold" fill="#102a56">${label}</text>`;});
 if(half!==null)for(const y of [5,H-5])shapes+=`<path d="M ${W/2-9} ${y} H ${W/2+9} M ${W/2} ${y-4} V ${y+4}" fill="none" stroke="#111" stroke-width="1.5"/>`;
 return `<svg class="${half===null?'maze-board':'maze-half'}" viewBox="${half===null?0:half*W/2} 0 ${half===null?W:W/2} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Maze jalan raya Bandar Polis ImAn yang boleh diselesaikan">${shapes}</svg>`;
}

function legend(){return `<div class="maze-legend">${locationNames.map((n,i)=>`<div>${image('location-'+(i+1),'','legend-art')}<span class="legend-number">${i+1}</span>${n}</div>`).join('')}</div>`;}

